import type { MetadataRoute } from "next";
import { CANVAS_COLORS, FOREST_GREEN } from "@/lib/theme";

/**
 * Web app manifest, served at /manifest.webmanifest. Icons are generated by
 * scripts/generate-icons.mts. The service worker (public/sw.js, registered
 * in the root layout) is what lets the installed app receive notifications.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "SoleUp",
    short_name: "SoleUp",
    description:
      "Decide what matters, plan realistic next steps, and review your progress.",
    start_url: "/home",
    scope: "/",
    display: "standalone",
    background_color: CANVAS_COLORS.light,
    theme_color: FOREST_GREEN,
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png" },
      {
        src: "/icons/maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
